  "<!doctype html><html lang=\"ja\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>PicoBlocks JOG</title>\n<style>body{font:16px system-ui;color:#273345;background:#fafafa;max-width:520px;margin:auto;padding:24px}h1{font-size:24px}p{color:#697485}section{display:grid;grid-template-columns:1fr 70px 70px 70px;align-items:center;gap:8px;padding:18px 0;border-bottom:1px solid #e1e5eb}button{touch-action:manipulation;font:600 20px system-ui;border:1px solid #dedbea;border-radius:12px;background:#f2f0fb;color:#51458a;min-height:58px}button:disabled{opacity:.4}output{text-align:center;font-variant-numeric:tabular-nums}.center{width:100%;margin-top:24px;font-size:16px}</style>\n<h1>PicoBlocks JOG</h1><p id=\"status\">接続を確認しています…</p>\n{0}\n<button disabled class=\"center\" id=\"center\">中央へ戻す · Space</button><p>各行のボタン、または同じキーで操作できます。<br>ボタン1回／キー入力1回で設定した幅だけ動きます。</p>\n<script>\nconst keys={1};let busy=false,online=false,lastKey=0;\nasync function request(path){if(busy)return;busy=true;try{const r=await fetch(path,{method:path==='/state'?'GET':'POST',cache:'no-store',signal:AbortSignal.timeout(2000)});if(!r.ok)throw Error();const v=await r.json();for(const a of Object.keys(v))document.getElementById(a).textContent=v[a];online=true;document.getElementById('status').textContent='接続済み · 表示は指令位置です';}catch(e){online=false;document.getElementById('status').textContent='通信できません。PicoのWi-Fi接続を確認してください。';}finally{busy=false;document.querySelectorAll('button').forEach(b=>b.disabled=!online);}}\ndocument.querySelectorAll('[data-axis]').forEach(b=>b.onclick=()=>request('/jog/'+b.dataset.axis+'/'+b.dataset.dir));\ndocument.getElementById('center').onclick=()=>request('/center');\ndocument.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey||e.target.closest('input,textarea,select,[contenteditable=true]'))return;if(!keys[e.code]&&e.code!=='Space')return;e.preventDefault();if(!online||document.hidden)return;if(e.repeat&&Date.now()-lastKey<100)return;lastKey=Date.now();if(e.code==='Space'){if(!e.repeat)request('/center');}else request('/jog/'+keys[e.code].join('/'));});\nrequest('/state');setInterval(()=>{if(!document.hidden)request('/state')},1500);\n</script></html>": "<!doctype html><html lang=\"en\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>PicoBlocks JOG</title>\n<style>body{font:16px system-ui;color:#273345;background:#fafafa;max-width:520px;margin:auto;padding:24px}h1{font-size:24px}p{color:#697485}section{display:grid;grid-template-columns:1fr 70px 70px 70px;align-items:center;gap:8px;padding:18px 0;border-bottom:1px solid #e1e5eb}button{touch-action:manipulation;font:600 20px system-ui;border:1px solid #dedbea;border-radius:12px;background:#f2f0fb;color:#51458a;min-height:58px}button:disabled{opacity:.4}output{text-align:center;font-variant-numeric:tabular-nums}.center{width:100%;margin-top:24px;font-size:16px}</style>\n<h1>PicoBlocks JOG</h1><p id=\"status\">Checking connection…</p>\n{0}\n<button disabled class=\"center\" id=\"center\">Return to center · Space</button><p>Use the buttons in each row or the matching keys.<br>Each click or key input moves by the configured step.</p>\n<script>\nconst keys={1};let busy=false,online=false,lastKey=0;\nasync function request(path){if(busy)return;busy=true;try{const r=await fetch(path,{method:path==='/state'?'GET':'POST',cache:'no-store',signal:AbortSignal.timeout(2000)});if(!r.ok)throw Error();const v=await r.json();for(const a of Object.keys(v))document.getElementById(a).textContent=v[a];online=true;document.getElementById('status').textContent='Connected · Commanded positions shown';}catch(e){online=false;document.getElementById('status').textContent='Cannot communicate. Check your connection to the Pico Wi-Fi.';}finally{busy=false;document.querySelectorAll('button').forEach(b=>b.disabled=!online);}}\ndocument.querySelectorAll('[data-axis]').forEach(b=>b.onclick=()=>request('/jog/'+b.dataset.axis+'/'+b.dataset.dir));\ndocument.getElementById('center').onclick=()=>request('/center');\ndocument.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey||e.target.closest('input,textarea,select,[contenteditable=true]'))return;if(!keys[e.code]&&e.code!=='Space')return;e.preventDefault();if(!online||document.hidden)return;if(e.repeat&&Date.now()-lastKey<100)return;lastKey=Date.now();if(e.code==='Space'){if(!e.repeat)request('/center');}else request('/jog/'+keys[e.code].join('/'));});\nrequest('/state');setInterval(()=>{if(!document.hidden)request('/state')},1500);\n</script></html>",
  "LCDに %1 を改行して表示": "LCD print %1 on a new line",
  "GEEK内蔵LCDへ表示。英数字・記号で1行15文字、8行。長文は折り返し、下端でスクロールします。日本語は?に置換します。": "Print to the GEEK LCD. ASCII letters, numbers and symbols; 15 columns × 8 rows. Wraps long text and scrolls at the bottom. Non-ASCII characters become ?.",
  "LCDの %1 行目に %2 を表示": "LCD row %1 show %2",
  "指定行を消して上書き。15文字まで。短い値に変わっても前の文字は残りません。": "Clear and overwrite this row, up to 15 characters. Shorter values leave no old text behind.",
  "LCDの文字をすべて消す": "LCD clear all text",
  "画面を黒くして、次の改行表示を1行目から始めます。": "Clear to black and restart the next log line at row 1.",
  "USBシリアル表示をLCDにも %1": "Mirror USB serial prints to LCD %1",
  "表示する": "on",
  "表示しない": "off",
  "「USBシリアルへ表示」ブロックの文字列をLCDへも表示します。USB受信・JOG通信・内部ログは対象外です。": "Also show “print to USB serial” block output on the LCD. Excludes USB input, JOG traffic, and internal logs.",
  "LCD文字表示": "LCD text",
